    def by_action(self, action: str) -> List[PlanEntry]:
        return [entry for entry in self.entries if entry.action == action]


def needs_update(source_path: str, target_path: str) -> bool:
    """目标文件是否需要被源文件覆盖。

    先用签名（大小+时间戳）快速判断；如果签名相同但我们还不能确定内容
    一致，就进行字节级比较。
    """
    source_sig = fsops.stat_signature(source_path)
    target_sig = fsops.stat_signature(target_path)

    if source_sig is None or target_sig is None:
        return True

    # 签名不同，肯定需要更新
    if source_sig != target_sig:
        return True

    # 签名相同，但可能内容不同（只是时间戳和大小碰巧一样）
    # 进行实际内容比较
    return not fsops.content_equal(source_path, target_path)


def build_plan(source_root: str, target_root: str) -> Plan:
    """计算从 ``source_root`` 到 ``target_root`` 的镜像同步计划。"""
    source_files = fsops.list_entries(source_root)
    target_files = fsops.list_entries(target_root)

    entries: List[PlanEntry] = []

    # 遍历源中的文件
    for key in sorted(source_files):
        source_path = source_files[key]
        target_path = fsops.join(target_root, key)

        if key not in target_files:
            # 目标中没有这个文件
            entries.append(
                PlanEntry(
                    CREATE,
                    key,
                    source_path,
                    target_path,
                )
            )
        elif needs_update(source_path, target_files[key]):
            # 目标中有但需要更新
            entries.append(
                PlanEntry(UPDATE, key, source_path, target_files[key])
            )
        else:
            # 内容一致，保持不变
            entries.append(
                PlanEntry(KEEP, key, source_path, target_files[key])
            )

    # 遍历目标中的文件，找出源中没有的
    for key in sorted(target_files):
        if key not in source_files:
            entries.append(PlanEntry(DELETE, key, None, target_files[key]))

    return Plan(entries)

